import 'dart:io' show Platform;
import 'dart:math';

import 'package:dio/dio.dart';
import 'package:flutter/foundation.dart';

import 'models.dart';
import 'apple_kit.dart';
import 'lyrics.dart';
import 'source.dart';

/// Apple Music, read through the Apple Music REST API and played through the
/// platform's own MusicKit player.
///
/// Two tokens are involved and both come from the system: the *developer*
/// token identifies this app and is generated by MusicKit itself (the app does
/// not ship a key), and the *music user* token says which Apple Music
/// account's library to read. Neither is a password and neither expires in a
/// way the app has to think about: re-connecting asks for fresh ones.
class AppleMusicAdapter implements LibraryAdapter {
  /// [musicKit] is injectable so the connect flow can be exercised without
  /// the plugin; the app never passes one.
  AppleMusicAdapter({MusicKitClient? musicKit, String? apiRoot})
    : _musicKit = musicKit ?? MusicKitClient(),
      _apiRoot = apiRoot ?? kAppleMusicApiRoot;

  final MusicKitClient _musicKit;

  /// The API root stored on a new connection. Tests point it at a local
  /// server; the app always uses Apple's.
  final String _apiRoot;

  @override
  LibraryKind get kind => LibraryKind.appleMusic;

  /// There is nothing to type: the account is whatever the system is signed
  /// into, so the setup form's fields are ignored.
  @override
  Future<SourceConfig> connect({
    required String baseUrl,
    required String username,
    required String password,
  }) async {
    if (!AppleMusicSource.isSupported) throw _unsupported;

    final musicKit = _musicKit;
    final status = await musicKit.requestAuthorization();
    if (!status) throw _denied;

    final developerToken = await musicKit.developerToken();
    if (developerToken.isEmpty) throw _noDeveloperToken;
    final userToken = await musicKit.userToken(developerToken);
    if (userToken.isEmpty) throw _denied;

    final config = SourceConfig(
      id: newSourceId(LibraryKind.appleMusic),
      kind: LibraryKind.appleMusic,
      baseUrl: _apiRoot,
      displayName: 'Apple Music',
      auth: {'developerToken': developerToken, 'userToken': userToken},
    );
    // One signed-in read proves both tokens work before the source is stored.
    await AppleMusicSource(config).verify();
    return config;
  }

  @override
  LibrarySource sourceFor(SourceConfig config) => AppleMusicSource(config);

  /// Apple Music signs in through the system: there is no address or
  /// password to type.
  @override
  bool get needsCredentials => false;

  /// Only iOS and macOS 14+ can play what this adapter reads.
  @override
  bool get isAvailable => AppleMusicSource.isSupported;

  static const _unsupported = LibraryException(
    'Apple Music is not available on this device.',
    messageKey: 'libraryAppleMusicUnsupported',
  );
  static const _denied = LibraryException(
    'Apple Music access was refused. Allow it in System Settings, then try again.',
    messageKey: 'libraryAppleMusicDenied',
  );
  static const _noDeveloperToken = LibraryException(
    'Apple Music did not issue a developer token for this app.',
    messageKey: 'libraryAppleMusicNoToken',
  );
}

/// The API root every Apple Music read is relative to.
const kAppleMusicApiRoot = 'https://api.music.apple.com';

/// One signed-in Apple Music account.
class AppleMusicSource extends LibrarySource {
  @override
  final SourceConfig config;
  final Dio _dio;

  AppleMusicSource(this.config)
    : _dio = Dio(
        BaseOptions(
          // The API root, kept as the stored address so nothing else has to
          // know that an Apple Music source has no user-typed host.
          baseUrl: config.baseUrl.isEmpty ? kAppleMusicApiRoot : config.baseUrl,
          connectTimeout: const Duration(seconds: 12),
          receiveTimeout: const Duration(seconds: 25),
          responseType: ResponseType.json,
          headers: {
            'Authorization': 'Bearer ${config.auth['developerToken'] ?? ''}',
            'Music-User-Token': config.auth['userToken'] ?? '',
            // Apple answers differently without it; the app has no
            // server-side proxy to localise reads.
            'Accept-Language': 'en',
          },
        ),
      );

  /// MusicKit's own player can only play on iOS 15+ and macOS 14+. Reads
  /// still work without it, but a library that cannot be heard is not a
  /// library the setup screen should offer.
  static bool get isSupported {
    if (kIsWeb) return false;
    if (Platform.isIOS) return true;
    if (!Platform.isMacOS) return false;
    final match = RegExp(r'Version (\d+)')
        .firstMatch(Platform.operatingSystemVersion);
    final major = match == null ? 0 : int.parse(match.group(1)!);
    return major >= 14;
  }

  /// Apple Music plays in-process: there is no stream URL, the system's
  /// player is handed the item instead.
  @override
  bool get usesPlatformPlayer => true;

  /// The account is the device's, not an address: Settings shows the kind
  /// alone rather than an API endpoint nobody typed.
  @override
  String get addressLabel => '';

  static const _signedOut = LibraryException(
    'This Apple Music account is not signed in. Connect it again from Settings.',
    messageKey: 'librarySignedOut',
  );

  /// Confirms both tokens still work.
  Future<void> verify() => _get('/v1/me/library/artists', query: {'limit': 1});

  Future<Map<String, dynamic>> _get(
    String path, {
    Map<String, dynamic>? query,
  }) async {
    if (config.auth['developerToken'] == null ||
        config.auth['userToken'] == null) {
      throw _signedOut;
    }
    final Response<dynamic> response;
    try {
      response = await _dio.get<dynamic>(path, queryParameters: query);
    } on DioException catch (error) {
      final status = error.response?.statusCode;
      if (status == 401 || status == 403) {
        throw LibraryException(
          'Apple Music refused the request (HTTP $status).',
          code: status,
          messageKey: status == 403
              ? 'libraryAppleMusicSubscription'
              : 'libraryAppleMusicSignedOut',
        );
      }
      if (error.type == DioExceptionType.badResponse) {
        throw LibraryException(
          'Apple Music returned HTTP $status.',
          code: status,
          messageKey: 'libraryHttpError',
          messageArgs: [status?.toString() ?? 'error'],
        );
      }
      throw describeAppleError(error);
    }

    final data = response.data;
    if (data is! Map) throw _malformed;
    return Map<String, dynamic>.from(data);
  }

  /// Every list endpoint answers with `{data: [...], next?}`.
  Future<List<Map<String, dynamic>>> _data(
    String path, {
    Map<String, dynamic>? query,
  }) async {
    final body = await _get(path, query: query);
    return _resources(body);
  }

  static List<Map<String, dynamic>> _resources(Map<String, dynamic> body) {
    final data = body['data'];
    if (data is! List) return const [];
    return [
      for (final item in data)
        if (item is Map) Map<String, dynamic>.from(item),
    ];
  }

  @override
  Future<List<LibraryAlbum>> recentlyAdded({int limit = 50}) async {
    // `recently-added` mixes albums and playlists; only albums belong on the
    // "newest" shelf.
    final items = await _data(
      '/v1/me/library/recently-added',
      query: {'limit': limit},
    );
    return [
      for (final item in items)
        if (item['type'] == 'library-albums') _album(item),
    ];
  }

  @override
  Future<List<LibraryAlbum>> albums({int limit = 60, int offset = 0}) async {
    final items = await _data(
      '/v1/me/library/albums',
      query: {'limit': limit, 'offset': offset},
    );
    return [for (final item in items) _album(item)];
  }

  @override
  Future<LibraryAlbum?> album(String albumId) async {
    final items = await _data('/v1/me/library/albums/${_path(albumId)}');
    return items.isEmpty ? null : _album(items.first);
  }

  @override
  Future<List<LibrarySong>> albumSongs(String albumId) async {
    final items = await _data('/v1/me/library/albums/${_path(albumId)}/tracks');
    return [for (final item in items) _song(item, albumId: albumId)];
  }

  @override
  Future<List<LibraryArtist>> artists() async {
    final items = await _data('/v1/me/library/artists', query: {'limit': 100});
    return [
      for (final item in items)
        LibraryArtist(
          sourceId: id,
          id: '${item['id']}',
          name: _attributes(item)['name'] as String? ?? 'Unknown artist',
        ),
    ];
  }

  @override
  Future<List<LibraryAlbum>> artistAlbums(String artistId) async {
    final items = await _data(
      '/v1/me/library/artists/${_path(artistId)}/albums',
    );
    return [for (final item in items) _album(item)];
  }

  @override
  Future<List<LibraryPlaylist>> playlists() async {
    final items = await _data(
      '/v1/me/library/playlists',
      query: {'limit': 100},
    );
    return [
      for (final item in items)
        LibraryPlaylist(
          sourceId: id,
          id: '${item['id']}',
          name: _attributes(item)['name'] as String? ?? 'Untitled playlist',
          duration: Duration.zero,
        ),
    ];
  }

  @override
  Future<List<LibrarySong>> playlistSongs(String playlistId) async {
    final items = await _data(
      '/v1/me/library/playlists/${_path(playlistId)}/tracks',
    );
    return [for (final item in items) _song(item)];
  }

  @override
  Future<List<LibrarySong>> search(String query, {int limit = 40}) async {
    final term = query.trim();
    if (term.isEmpty) return const [];
    final body = await _get(
      '/v1/me/library/search',
      query: {'term': term, 'types': 'library-songs', 'limit': limit},
    );
    final results = body['results'];
    final songs = results is Map ? results['library-songs'] : null;
    if (songs is! Map) return const [];
    return [
      for (final item in _resources(Map<String, dynamic>.from(songs)))
        _song(item),
    ];
  }

  /// There is no random endpoint, so a page from a random offset is shuffled.
  ///
  /// The offset is bounded by the library's own `meta.total`: picking blind
  /// inside a fixed range returns nothing at all for a library smaller than
  /// that range.
  @override
  Future<List<LibrarySong>> randomSongs({int size = 40}) async {
    final first = await _get('/v1/me/library/songs', query: {'limit': 1});
    final meta = first['meta'];
    final total = meta is Map ? (meta['total'] as num?)?.toInt() ?? 0 : 0;
    final offset = total > size ? Random().nextInt(total - size) : 0;
    final items = await _data(
      '/v1/me/library/songs',
      query: {'limit': size, 'offset': offset},
    );
    return [for (final item in items) _song(item)]..shuffle();
  }

  /// Apple does not expose library lyrics over the API; the resolver falls
  /// through to LRCLIB.
  @override
  Future<Lyrics> lyrics(LibrarySong song) async => Lyrics.empty;

  /// Never called: Apple Music items are played by [AppleMusicSource]'s
  /// platform player, not opened as a URL.
  @override
  Uri streamUri(LibrarySong song) => throw const LibraryException(
    'Apple Music tracks are played by the system player.',
    messageKey: 'libraryAppleMusicNoStream',
  );

  /// The art id is Apple's own template URL (`.../{w}x{h}bb.jpg`), so a
  /// cover is resized by substituting the size the widget actually paints.
  @override
  Uri? artworkUri(String? artId, {int size = 600}) {
    if (artId == null || artId.isEmpty) return null;
    return Uri.tryParse(
      artId
          .replaceAll('{w}', '$size')
          .replaceAll('{h}', '$size')
          .replaceAll('{c}', 'bb')
          .replaceAll('{f}', 'jpg'),
    );
  }

  static String _path(String id) => Uri.encodeComponent(id);

  static Map<String, dynamic> _attributes(Map<String, dynamic> json) {
    final attributes = json['attributes'];
    return attributes is Map ? Map<String, dynamic>.from(attributes) : const {};
  }

  /// A cover template, or null when the item has none.
  static String? _artTemplate(Map<String, dynamic> attributes) {
    final artwork = attributes['artwork'];
    if (artwork is! Map) return null;
    final url = artwork['url'];
    return url is String && url.isNotEmpty ? url : null;
  }

  static Duration _duration(Map<String, dynamic> attributes) => Duration(
    milliseconds:
        (attributes['durationInMillis'] as num?)?.toInt() ??
        (attributes['durationInMillis'] as num?)?.round() ??
        0,
  );

  static int? _year(Map<String, dynamic> attributes) {
    final release = attributes['releaseDate'];
    if (release is! String || release.isEmpty) return null;
    return int.tryParse(release.substring(0, min(4, release.length)));
  }

  static String? _genre(Map<String, dynamic> attributes) {
    final genres = attributes['genreNames'];
    if (genres is! List) return null;
    // Apple's last genre is always "Music", which says nothing.
    final names = [
      for (final g in genres)
        if (g is String && g != 'Music') g,
    ];
    return names.isEmpty ? null : names.first;
  }

  LibrarySong _song(Map<String, dynamic> json, {String? albumId}) {
    final attributes = _attributes(json);
    return LibrarySong(
      sourceId: id,
      id: '${json['id']}',
      title: attributes['name'] as String? ?? 'Untitled',
      artist: attributes['artistName'] as String?,
      album: attributes['albumName'] as String?,
      albumId: albumId,
      artId: _artTemplate(attributes),
      duration: _duration(attributes),
      track: (attributes['trackNumber'] as num?)?.toInt(),
      discNumber: (attributes['discNumber'] as num?)?.toInt(),
      year: _year(attributes),
      genre: _genre(attributes),
    );
  }

  LibraryAlbum _album(Map<String, dynamic> json) {
    final attributes = _attributes(json);
    return LibraryAlbum(
      sourceId: id,
      id: '${json['id']}',
      name: attributes['name'] as String? ?? 'Untitled',
      artist: attributes['artistName'] as String?,
      artId: _artTemplate(attributes),
      songCount: (attributes['trackCount'] as num?)?.toInt(),
      duration: Duration.zero,
      year: _year(attributes),
      genre: _genre(attributes),
    );
  }
}

const _malformed = LibraryException(
  'Malformed Apple Music response.',
  messageKey: 'libraryMalformedResponse',
);

/// Transport failures the REST layer can diagnose itself, in the same
/// vocabulary the other adapters use.
LibraryException describeAppleError(DioException error) {
  switch (error.type) {
    case DioExceptionType.connectionTimeout:
    case DioExceptionType.receiveTimeout:
    case DioExceptionType.sendTimeout:
    case DioExceptionType.transformTimeout:
      return const LibraryException(
        'Apple Music took too long to respond.',
        messageKey: 'libraryTimeout',
      );
    case DioExceptionType.connectionError:
      return const LibraryException(
        'Could not reach Apple Music. Check your network.',
        messageKey: 'libraryUnreachableNetwork',
      );
    case DioExceptionType.badCertificate:
      return const LibraryException(
        "Apple Music's certificate is not valid.",
        messageKey: 'libraryBadCertificate',
      );
    case DioExceptionType.cancel:
      return const LibraryException(
        'Request cancelled.',
        messageKey: 'libraryRequestCancelled',
      );
    case DioExceptionType.badResponse:
      return const LibraryException(
        'Apple Music returned an error.',
        messageKey: 'libraryUnknownNetwork',
      );
    case DioExceptionType.unknown:
      return LibraryException(error.message ?? 'Unknown network error.');
  }
}
